    ],
    [
        {"role": "system", "content": SYSTEM},
        {"role": "user", "content": "Solve for x: 2x + 5 = 17."},
        {"role": "assistant", "content": "2x + 5 = 17\n2x = 12\nx = 6."}
    ],
    [
        {"role": "system", "content": SYSTEM},
        {"role": "user", "content": "What's the capital of France?"},
